import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import TripMap from './TripMap';
import DataChart from './DataChart'; // We will create this file next

const TripGroupDetail = () => {
    const { groupId } = useParams();
    const [groupData, setGroupData] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');

    useEffect(() => {
        const fetchGroupData = async () => {
            setLoading(true); // Ensure loading is true at the start
            try {
                const response = await axios.get(`http://localhost:5001/api/trip-groups/${groupId}`);
                setGroupData(response.data);
                setError(''); // Clear previous errors
            } catch (err) {
                setError('Failed to fetch trip group details.');
                console.error(err);
                setGroupData(null); // Clear previous data on error
            } finally {
                setLoading(false);
            }
        };

        fetchGroupData();
    }, [groupId]);

    // --- FIX: Robust Guard Clauses ---
    // These now correctly handle all initial states and prevent rendering with null data.
    if (loading) {
        return <div>Loading trip group data...</div>;
    }

    if (error) {
        return <div style={{ color: 'red' }}>ERROR: {error}</div>;
    }

    if (!groupData || !groupData.logs || groupData.logs.length === 0) {
        return <div>No logs found for this trip group.</div>;
    }
    // --- END FIX ---

    return (
        <div className="trip-group-detail-container">
            <h2>Trip Group: {groupId}</h2>
            {groupData.logs.map(log => (
                <div key={log.log_id} className="log-container-box">
                    <h3>Log File: {log.file_name}</h3>
                    <p>Duration: {(log.trip_duration_seconds / 60).toFixed(2)} minutes</p>

                    <div className="trip-details-layout">
                        <div className="trip-map-container">
                            <TripMap 
                                gpsData={groupData.gps_data[log.log_id]} 
                                columns={groupData.log_data[log.log_id].columns} 
                            />
                        </div>
                        <div className="data-plot-container">
                            <DataChart
                                logData={groupData.log_data[log.log_id].data}
                                columns={groupData.log_data[log.log_id].columns}
                            />
                        </div>
                    </div>
                </div>
            ))}
        </div>
    );
};

export default TripGroupDetail;
